const OLD_STORE = 'kbh_v3';
const STORE = 'kbh_v4';
let S = null; // session
let _uid = null, _euid = null, _eunid = null;
let _uf = 'All', _us = '';
let _cid = null, _cs = '';
let _rt = 'unit', _rs = 'all', _at = 'users';
let _tmr = null, _coid = null, _xlrows = [];
let _prevPg = null; // Task 1: back navigation
const APP_BUILD='2026-05-07-fix-rrec-2';
let _leakGuardOn=false;

function seedDB() {
  return {
    companies:[{id:'co_kbh',name:'Nexunova',code:'NXN',fullName:'Nexunova'}],
    users:[
      {id:'ua',username:'admin',password:'admin123',name:'Admin',role:'admin',companyIds:['co_kbh'],createdAt:'2026-01-01'},
      {id:'us',username:'staff',password:'staff123',name:'Staff',role:'user',companyIds:['co_kbh'],createdAt:'2026-01-01'}
    ],
    units:{co_kbh:SEED_UNITS},
    recoveries:{co_kbh:[]},
    contacts:{co_kbh:[]},
    log:[]
  };
}
function gdb(){
  try{
    // Task 8: migrate from kbh_v3 to kbh_v4
    if(!localStorage.getItem(STORE)&&localStorage.getItem(OLD_STORE)){
      localStorage.setItem(STORE,localStorage.getItem(OLD_STORE));
    }
    const r=localStorage.getItem(STORE);
    if(!r){const d=seedDB();localStorage.setItem(STORE,JSON.stringify(d));return d;}
    const d=JSON.parse(r);
    // V3→V4 migration: embed existing recovery sums directly into u.totalPaid/pendingAmount
    if(!d._migv4){
      const recs=d.recoveries||{};
      Object.keys(recs).forEach(cid=>{
        const arr=recs[cid]||[];if(!arr.length)return;
        const m={};arr.forEach(r=>{m[r.uid]=(m[r.uid]||0)+Number(r.amt);});
        (d.units[cid]||[]).forEach(u=>{
          if(m[u.id]){
            u.totalPaid=Number(u.totalPaid||0)+m[u.id];
            u.pendingAmount=Math.max(0,Number(u.totalPrice||0)-u.totalPaid);
          }
        });
      });
      d._migv4=true;localStorage.setItem(STORE,JSON.stringify(d));
    }
    // Task 4A: sanitize malformed dates
    Object.keys(d.units||{}).forEach(cid=>{
      (d.units[cid]||[]).forEach(u=>{
        if(u.lastPaymentDate&&!/^\d{4}-\d{2}-\d{2}$/.test(u.lastPaymentDate)){
          u.lastPaymentDate='';
        }
      });
    });
    // Ensure settings exist (Task 6C)
    d.settings=d.settings||{overdueDays:30};
    return d;
  }catch(e){const d=seedDB();localStorage.setItem(STORE,JSON.stringify(d));return d;}
}
function sdb(d){
  try{
    const str=JSON.stringify(d);
    localStorage.setItem(STORE,str);
    // Also keep a session backup
    try{sessionStorage.setItem(STORE+'_bk',str);}catch(e){}
    // Track last save time
    localStorage.setItem(STORE+'_ts',new Date().toISOString());
    // Storage usage warning
    const used=new Blob([str]).size;
    if(used>4*1024*1024){toast('⚠️ Storage nearly full — please download backup from Admin Panel!','warn');}
  }catch(e){
    // localStorage full — try to recover from session backup
    const bk=sessionStorage.getItem(STORE+'_bk');
    if(bk){try{localStorage.setItem(STORE,bk);}catch(e2){}}
    toast('⚠️ Storage error! Download backup immediately from Admin Panel','err');
  }
}

